// gateModule is the ResolveGates fixture: two config-enabled chain slots and
// one config-disabled one (a pref must never revive a disabled binding).
func gateModule() module.Module {
	return module.Module{ID: "tv", MetadataSources: []module.MetadataSourceBinding{
		{PluginID: "alpha", CapabilityID: "default", Priority: 1, Enabled: true, AuthMode: "SERVER"},
		{PluginID: "beta", CapabilityID: "default", Priority: 2, Enabled: true},
		{PluginID: "gamma", CapabilityID: "default", Priority: 3, Enabled: false},
	}}
}

// enabledBy indexes a resolved binding set by plugin id.
func enabledBy(srcs []module.MetadataSourceBinding) map[string]bool {
	out := make(map[string]bool, len(srcs))
	for _, src := range srcs {
		out[src.PluginID] = src.Enabled
	}
	return out
}

// assertEnabled compares a resolved set against the wanted Enabled per plugin.
func assertEnabled(t *testing.T, got, want map[string]bool) {
	t.Helper()
	if len(got) != len(want) {
		t.Fatalf("resolved %d bindings, want %d: %v", len(got), len(want), got)
	}
	for id, w := range want {
		if got[id] != w {
			t.Fatalf("%s.Enabled = %v, want %v (resolved set: %v)", id, got[id], w, got)
		}
	}
}

// TestGateResolution pins the D3 gate materialization: ResolveGates returns
// binding COPIES with Enabled=false written into gated ones (module-scope and
// library-scope rows, conjunction, inherit-when-absent), the config slice is
// never mutated, and the DERIVATION consumes the resolved set — a gated source
// never appears pending, including through the extras path's synthesized
// defaults, while nongated sources derive unchanged.
func TestGateResolution(t *testing.T) {
	ctx := context.Background()
	const modID = "tv"
	lib, other := int64(7), int64(9)

	t.Run("binding_resolution", func(t *testing.T) {
		cases := []struct {
			name  string
			prefs []store.MetadataSourcePref
			libID int64
			want  map[string]bool
		}{
			{
				name:  "absent_rows_inherit_config",
				prefs: nil,
				libID: lib,
				want:  map[string]bool{"alpha": true, "beta": true, "gamma": false},
			},
			{
				name:  "module_gate_only",
				prefs: []store.MetadataSourcePref{{ModuleID: modID, PluginID: "alpha", Enabled: false}},
				libID: lib,
				want:  map[string]bool{"alpha": false, "beta": true, "gamma": false},
			},
			{
				name:  "library_gate_only_scoped_to_its_library",
				prefs: []store.MetadataSourcePref{{ModuleID: modID, LibraryID: lib, PluginID: "alpha", Enabled: false}},
				libID: lib,
				want:  map[string]bool{"alpha": false, "beta": true, "gamma": false},
			},
			{
				name:  "library_gate_does_not_leak_to_other_libraries",
				prefs: []store.MetadataSourcePref{{ModuleID: modID, LibraryID: lib, PluginID: "alpha", Enabled: false}},
				libID: other,
				want:  map[string]bool{"alpha": true, "beta": true, "gamma": false},
			},
			{
				name: "gate_conjunction_module_and_library",
				prefs: []store.MetadataSourcePref{
					{ModuleID: modID, PluginID: "alpha", Enabled: false},
					{ModuleID: modID, LibraryID: lib, PluginID: "alpha", Enabled: false},
				},
				libID: lib,
				want:  map[string]bool{"alpha": false, "beta": true, "gamma": false},
			},
			{
				name: "library_row_overrides_module_gate",
				prefs: []store.MetadataSourcePref{
					{ModuleID: modID, PluginID: "alpha", Enabled: false},
					{ModuleID: modID, LibraryID: lib, PluginID: "alpha", Enabled: true},
				},
				libID: lib,
				want:  map[string]bool{"alpha": true, "beta": true, "gamma": false},
			},
			{
				name: "library_gate_overrides_module_allow",
				prefs: []store.MetadataSourcePref{
					{ModuleID: modID, PluginID: "alpha", Enabled: true},
					{ModuleID: modID, LibraryID: lib, PluginID: "alpha", Enabled: false},
				},
				libID: lib,
				want:  map[string]bool{"alpha": false, "beta": true, "gamma": false},
			},
			{
				name:  "gate_never_revives_disabled_binding",
				prefs: []store.MetadataSourcePref{{ModuleID: modID, PluginID: "gamma", Enabled: true}},
				libID: lib,
				want:  map[string]bool{"alpha": true, "beta": true, "gamma": false},
			},
			{
				name: "foreign_module_rows_ignored",
				prefs: []store.MetadataSourcePref{
					{ModuleID: "movie", PluginID: "alpha", Enabled: false},
					{ModuleID: modID, LibraryID: other, PluginID: "beta", Enabled: false},
				},
				libID: lib,
				want:  map[string]bool{"alpha": true, "beta": true, "gamma": false},
			},
		}
		for _, tc := range cases {
			t.Run(tc.name, func(t *testing.T) {
				mod := gateModule()
				assertEnabled(t, enabledBy(ResolveGates(mod, tc.prefs, tc.libID)), tc.want)
			})
		}
	})

	t.Run("returns_copies_config_untouched", func(t *testing.T) {
		mod := gateModule()
		prefs := []store.MetadataSourcePref{{ModuleID: modID, PluginID: "alpha", Enabled: false}}
		gated := ResolveGates(mod, prefs, lib)
		gated[0].Enabled = true // mutating a copy must not reach the config slice
		assertEnabled(t, enabledBy(mod.MetadataSources),
			map[string]bool{"alpha": true, "beta": true, "gamma": false})
		if len(gated) != len(mod.MetadataSources) {
			t.Fatalf("resolved %d bindings, want %d", len(gated), len(mod.MetadataSources))
		}
	})

	t.Run("gated_chain_source_never_pending", func(t *testing.T) {
		s, reg := queueTestStore(t)
		libID, err := s.CreateLibrary(ctx, "tv", filepath.Join(t.TempDir(), "lib1"), "TV")
		if err != nil {
			t.Fatalf("CreateLibrary: %v", err)
		}
		putItem(t, s, "i_gate", libID, statusPending, baseDoc("Show/S01E01.mkv"))
		// Module-scope gate: tv-parser derives nothing; tmdb (nongated) still does.
		if err := s.UpsertMetadataSourcePref(ctx, store.MetadataSourcePref{
			ModuleID: "tv", PluginID: "tv-parser", Enabled: false,
		}); err != nil {
			t.Fatalf("UpsertMetadataSourcePref: %v", err)
		}
		q := NewQueue(Deps{Store: s, Modules: reg}, QueueConfig{})
		tasks, err := q.deriveLibrary(ctx, libID)
		if err != nil {
			t.Fatalf("deriveLibrary: %v", err)
		}
		got := pluginIDs(tasks)
		if got["tv-parser"] {
			t.Fatalf("gated tv-parser derived into the queue: %v", got)
		}
		if !got["tmdb"] {
			t.Fatalf("nongated tmdb lost its pending task (gate leaked): %v", got)
		}
	})

	t.Run("library_gate_scopes_derivation", func(t *testing.T) {
		s, reg := queueTestStore(t)
		lib1, err := s.CreateLibrary(ctx, "tv", filepath.Join(t.TempDir(), "lib1"), "TV")
		if err != nil {
			t.Fatalf("CreateLibrary lib1: %v", err)
		}
		lib2, err := s.CreateLibrary(ctx, "tv", filepath.Join(t.TempDir(), "lib2"), "TV")
		if err != nil {
			t.Fatalf("CreateLibrary lib2: %v", err)
		}
		putItem(t, s, "i_l1", lib1, statusPending, baseDoc("Show/S01E01.mkv"))
		putItem(t, s, "i_l2", lib2, statusPending, baseDoc("Show/S01E02.mkv"))
		if err := s.UpsertMetadataSourcePref(ctx, store.MetadataSourcePref{
			ModuleID: "tv", LibraryID: lib1, PluginID: "tv-parser", Enabled: false,
		}); err != nil {
			t.Fatalf("UpsertMetadataSourcePref: %v", err)
		}
		q := NewQueue(Deps{Store: s, Modules: reg}, QueueConfig{})
		tasks1, err := q.deriveLibrary(ctx, lib1)
		if err != nil {
			t.Fatalf("deriveLibrary lib1: %v", err)
		}
		if pluginIDs(tasks1)["tv-parser"] {
			t.Fatalf("library-gated tv-parser derived in scope: %v", pluginIDs(tasks1))
		}
		tasks2, err := q.deriveLibrary(ctx, lib2)
		if err != nil {
			t.Fatalf("deriveLibrary lib2: %v", err)
		}
		if !pluginIDs(tasks2)["tv-parser"] {
			t.Fatalf("tv-parser gated out of an unscoped library: %v", pluginIDs(tasks2))
		}
	})

	t.Run("gated_extra_derives_nothing", func(t *testing.T) {
		s, reg := queueTestStore(t)
		libID, err := s.CreateLibrary(ctx, "tv", filepath.Join(t.TempDir(), "lib1"), "TV")
		if err != nil {
			t.Fatalf("CreateLibrary: %v", err)
		}
		// Chain done: only the element-attached anitomy (synthesized
		// Enabled: true default) could derive — the gate must mute it too.
		putItem(t, s, "i_extra", libID, statusEnriched, chainDoneDoc("Show/S01E01.mkv"))
		attach(t, s, "i_extra", "anitomy")
		if err := s.UpsertMetadataSourcePref(ctx, store.MetadataSourcePref{
			ModuleID: "tv", PluginID: "anitomy", Enabled: false,
		}); err != nil {
			t.Fatalf("UpsertMetadataSourcePref: %v", err)
		}
		q := NewQueue(Deps{Store: s, Modules: reg}, QueueConfig{})
		tasks, err := q.deriveLibrary(ctx, libID)
		if err != nil {
			t.Fatalf("deriveLibrary: %v", err)
		}
		for _, tk := range tasks {
			if tk.rowID == "i_extra" {
				t.Fatalf("gated extra derived work: %+v", tk)
			}
		}
	})

	t.Run("ungated_extra_still_derives", func(t *testing.T) {
		s, reg := queueTestStore(t)
		libID, err := s.CreateLibrary(ctx, "tv", filepath.Join(t.TempDir(), "lib1"), "TV")
		if err != nil {
			t.Fatalf("CreateLibrary: %v", err)
		}
		putItem(t, s, "i_extra", libID, statusEnriched, chainDoneDoc("Show/S01E01.mkv"))
		attach(t, s, "i_extra", "anitomy")
		q := NewQueue(Deps{Store: s, Modules: reg}, QueueConfig{})
		tasks, err := q.deriveLibrary(ctx, libID)
		if err != nil {
			t.Fatalf("deriveLibrary: %v", err)
		}
		found := false
		for _, tk := range tasks {
			if tk.rowID == "i_extra" && tk.pluginID == "anitomy" {
				found = true
			}
		}
		if !found {
			t.Fatalf("(i_extra, anitomy) not derived without gates; tasks = %v", pluginIDs(tasks))
		}
	})

	// The seeded tv module is the shared fixture; a module-gate sweep must
	// not disturb the live derivation of an unrelated item type (the series
	// lane consumes the same resolved set).
	t.Run("gated_series_source_never_pending", func(t *testing.T) {
		s, reg := queueTestStore(t)
		libID, err := s.CreateLibrary(ctx, "tv", filepath.Join(t.TempDir(), "lib1"), "TV")
		if err != nil {
			t.Fatalf("CreateLibrary: %v", err)
		}
		if err := s.PutSeries(ctx, store.Series{
			ID: "s_gate", ModuleID: "tv", LibraryID: libID, Status: statusPending,
			Document: mustJSON(t, baseDoc("Show")),
		}); err != nil {
			t.Fatalf("PutSeries: %v", err)
		}
		if err := s.UpsertMetadataSourcePref(ctx, store.MetadataSourcePref{
			ModuleID: "tv", PluginID: "tmdb", Enabled: false,
		}); err != nil {
			t.Fatalf("UpsertMetadataSourcePref: %v", err)
		}
		q := NewQueue(Deps{Store: s, Modules: reg}, QueueConfig{})
		tasks, err := q.deriveLibrary(ctx, libID)
		if err != nil {
			t.Fatalf("deriveLibrary: %v", err)
		}
		got := pluginIDs(tasks)
		if got["tmdb"] {
			t.Fatalf("gated tmdb derived for the series row: %v", got)
		}
		if !got["tv-parser"] {
			t.Fatalf("nongated tv-parser lost its series task (gate leaked): %v", got)
		}
	})
}

// mustJSON marshals a document map for direct row seeding.
func mustJSON(t *testing.T, doc map[string]any) []byte {
	t.Helper()
	b, err := json.Marshal(doc)
	if err != nil {
		t.Fatalf("marshal document: %v", err)
	}
	return b
}
